/*
 * Timed practices (breathing, grounding, a minute of silence, stretching, eyes, rest between sets) and the quiet background noise.
 * A script is a list of beats «at t ms say …»; the runner fires them with timers and tells the window (`veyrarc:practice`), where the
 * voice layer shows and speaks each line. Nothing is stored and no file is played: the noise is generated by Web Audio.
 */
export type Beat = { at: number; say: string };
export type PracticeEvent = { id: string; text: string; done?: boolean };

let timers: ReturnType<typeof setTimeout>[] = [];
let current: { id: string; endsAt: number; onEnd?: () => void } | null = null;

const emit = (detail: PracticeEvent) => { try { window.dispatchEvent(new CustomEvent('veyrarc:practice', { detail })); } catch { /* no window */ } };

export const scriptActive = () => current?.id ?? null;
export const scriptRemainingMs = () => (current ? Math.max(0, current.endsAt - Date.now()) : 0);

export function stopScript(): boolean {
  if (!current) return false;
  timers.forEach(clearTimeout); timers = [];
  current = null;
  try { window.speechSynthesis?.cancel(); } catch { /* no speech */ }
  return true;
}

/** play the beats; the closing line (`endSay`) comes at `totalMs` with a soft vibration */
export function runScript(id: string, beats: Beat[], totalMs: number, endSay: string, onEnd?: () => void) {
  stopScript();
  current = { id, endsAt: Date.now() + totalMs, onEnd };
  const later = (f: () => void, ms: number) => { const t = setTimeout(f, ms); (t as { unref?: () => void }).unref?.(); timers.push(t); };
  for (const b of beats) later(() => emit({ id, text: b.say }), b.at);
  later(() => {
    const done = current?.onEnd;
    current = null; timers = [];
    try { navigator.vibrate?.([120, 80, 120]); } catch { /* no vibration */ }
    emit({ id, text: endSay, done: true });
    done?.();
  }, totalMs);
}

/* ── breathing, grounding, a pause, stretching, eyes, rest ── */
const cycle = (n: number, len: number, parts: [number, string][]): Beat[] =>
  Array.from({ length: n }, (_, i) => parts.map(([at, say]) => ({ at: i * len + at, say }))).flat();

export type Practice = { beats: Beat[]; totalMs: number; intro: string; end: string };
export function practiceOf(id: string, ru: boolean, o: { minutes?: number; seconds?: number } = {}): Practice | null {
  const s = (n: number) => n * 1000;
  switch (id) {
    case 'breathe478': {
      const b = cycle(4, s(19), ru ? [[0, 'Вдох'], [s(4), 'Задержка'], [s(11), 'Выдох']] : [[0, 'Breathe in'], [s(4), 'Hold'], [s(11), 'Breathe out']]);
      return { beats: b, totalMs: s(76), intro: ru ? 'Дыхание четыре-семь-восемь. Четыре цикла. Вдох носом' : 'Breathing 4-7-8, four rounds. In through the nose', end: ru ? 'Хорошо. Четыре цикла позади' : 'Well done. Four rounds done' };
    }
    case 'box': {
      const b = cycle(4, s(16), ru ? [[0, 'Вдох'], [s(4), 'Пауза'], [s(8), 'Выдох'], [s(12), 'Пауза']] : [[0, 'Breathe in'], [s(4), 'Pause'], [s(8), 'Breathe out'], [s(12), 'Pause']]);
      return { beats: b, totalMs: s(64), intro: ru ? 'Дыхание квадратом, по четыре секунды. Начинаем' : 'Box breathing, four seconds each. Here we go', end: ru ? 'Хорошо. Минута дыхания позади' : 'Well done. A minute of breathing is done' };
    }
    case 'ground': {
      const steps = ru
        ? ['Назовите пять вещей, которые видите', 'Четыре вещи, которых можете коснуться', 'Три звука, которые слышите', 'Два запаха', 'Один вкус']
        : ['Name five things you can see', 'Four things you can touch', 'Three sounds you can hear', 'Two smells', 'One taste'];
      return { beats: steps.map((say, i) => ({ at: i * s(20), say })), totalMs: s(100), intro: ru ? 'Заземление: пять, четыре, три, два, один' : 'Grounding: five, four, three, two, one', end: ru ? 'Вы здесь. Дышите спокойно' : 'You are here. Breathe easy' };
    }
    case 'pause':
      return { beats: [], totalMs: s(60), intro: ru ? 'Минута тишины. Просто дышите' : 'A minute of quiet. Just breathe', end: ru ? 'Минута прошла' : 'The minute is over' };
    case 'stretch': {
      const min = Math.max(2, Math.min(15, Math.round(o.minutes ?? 5)));
      const names = ru ? ['Шея: плавные наклоны', 'Плечи: круги назад', 'Спина: наклон вперёд', 'Бёдра: выпад', 'Ноги: потяните переднюю поверхность бедра', 'Запястья: вращения'] : ['Neck: slow tilts', 'Shoulders: circles back', 'Back: forward fold', 'Hips: lunge', 'Legs: quad stretch', 'Wrists: rotations'];
      const each = (min * 60 * 1000) / names.length;
      return { beats: names.map((say, i) => ({ at: Math.round(i * each), say })), totalMs: min * 60 * 1000, intro: ru ? `Растяжка ${min} минут, шесть упражнений` : `${min}-minute stretch, six moves`, end: ru ? 'Растяжка закончена' : 'Stretch finished' };
    }
    case 'eyes': {
      const b = cycle(2, s(30), ru ? [[0, 'Посмотрите вдаль на двадцать секунд'], [s(20), 'Поморгайте']] : [[0, 'Look far away for twenty seconds'], [s(20), 'Blink slowly']]);
      return { beats: b, totalMs: s(60), intro: ru ? 'Разминка для глаз, правило двадцать-двадцать-двадцать' : 'Eye break, the 20-20-20 rule', end: ru ? 'Глаза отдохнули' : 'Your eyes had a rest' };
    }
    case 'rest': {
      const sec = Math.max(10, Math.min(600, Math.round(o.seconds ?? 60)));
      const beats: Beat[] = sec > 30 ? [{ at: s(sec - 10), say: ru ? 'Десять секунд' : 'Ten seconds' }] : [];
      return { beats, totalMs: s(sec), intro: ru ? `Отдых ${sec} секунд` : `Rest for ${sec} seconds`, end: ru ? 'Отдых закончен. Следующий подход' : 'Rest is over. Next set' };
    }
  }
  return null;
}

/* ── quiet background noise ── */
export type NoiseKind = 'white' | 'rain' | 'brown';
let ctx: AudioContext | null = null;
let noise: { src: AudioBufferSourceNode; gain: GainNode; stop: ReturnType<typeof setTimeout> } | null = null;
export const noiseOn = () => !!noise;
export function stopNoise(): boolean {
  if (!noise) return false;
  const n = noise;
  noise = null;
  clearTimeout(n.stop);
  try { n.gain.gain.setTargetAtTime(0, ctx!.currentTime, 0.2); setTimeout(() => { try { n.src.stop(); } catch { /* stopped */ } }, 600); } catch { /* ignore */ }
  return true;
}
export function startNoise(kind: NoiseKind, maxMinutes = 90): boolean {
  stopNoise();
  try {
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return false;
    ctx = ctx ?? new AC();
    void ctx.resume();
    const len = ctx.sampleRate * 4;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      if (kind === 'brown') { last = (last + 0.02 * w) / 1.02; d[i] = last * 3.5; } else d[i] = w * (kind === 'rain' ? 0.6 : 0.4);
    }
    const src = ctx.createBufferSource();
    src.buffer = buf; src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = kind === 'rain' ? 'bandpass' : 'lowpass';
    filter.frequency.value = kind === 'rain' ? 2400 : kind === 'brown' ? 600 : 8000;
    const gain = ctx.createGain();
    gain.gain.value = 0;
    gain.gain.setTargetAtTime(0.18, ctx.currentTime, 0.4);
    src.connect(filter).connect(gain).connect(ctx.destination);
    src.start();
    noise = { src, gain, stop: setTimeout(() => stopNoise(), maxMinutes * 60000) };
    return true;
  } catch { return false; }
}
